    return {'i_h':i_h,'i_w':i_w,'i_min':min(i_h,i_w),'i_max':max(i_h,i_w),'t':t,
            'b_h':b_h,'b_w':b_w,'b_min':min(b_h,b_w),'b_max':max(b_h,b_w),
